import schedule.*;import java.time.*;
public class Main {public static void main(String[]args){Administration manage=new SchoolSchedule(2);Queries query=(Queries)manage;manage.create();manage.createSubject("s1","Алгебра");manage.createSubject("s2","История");manage.createTeacher("t1","Иванов");manage.createTeacher("t2","Петров");manage.group("g1","9А");manage.group("g2","9Б");manage.add(new Lesson("l1",LocalDate.of(2026,10,19),LocalTime.of(9,0),"s1","t1","g1","101",Lesson.Kind.THEORY,""));manage.add(new Lesson("l2",LocalDate.of(2026,10,19),LocalTime.of(10,0),"s2","t2","g1","102",Lesson.Kind.THEORY,""));manage.add(new Lesson("l3",LocalDate.of(2026,10,20),LocalTime.of(9,0),"s1","t1","g2","101",Lesson.Kind.THEORY,""));manage.add(new Lesson("l4",LocalDate.of(2026,10,20),LocalTime.of(10,0),"s2","t2","g2","102",Lesson.Kind.THEORY,""));System.out.println(query.forTeacher("t1")+"; число="+query.teacherCount("t1"));manage.cancel("l1");manage.changeRoom("l3","C");System.out.println(query.forTeacher("t1")+"; число="+query.teacherCount("t1"));}}
